import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const archiveRaw = "/Users/vincet/Documents/ttgame/codex_thread_archive/raw";
const codexHome = "/Users/vincet/.codex";
const outDir = "/Users/vincet/Documents/aimusic/codex_recovery";
const sessionsDir = path.join(codexHome, "sessions");
const stateDb = path.join(codexHome, "state_5.sqlite");
const sessionIndex = path.join(codexHome, "session_index.jsonl");

const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupDir = path.join(outDir, `pre_restore_backup_${timestamp}`);

function sh(cmd, args, opts = {}) {
  return execFileSync(cmd, args, { encoding: "utf8", ...opts });
}

function listRollouts() {
  const output = sh("find", [archiveRaw, "-type", "f", "-name", "*.jsonl"]);
  return output.trim().split(/\n/).filter(Boolean).sort();
}

function parseRollout(file) {
  const lines = fs.readFileSync(file, "utf8").split(/\n/).filter(Boolean);
  let meta = null;
  let title = "";
  let firstUser = "";
  let lastTimestamp = "";

  for (const line of lines) {
    let row;
    try {
      row = JSON.parse(line);
    } catch {
      continue;
    }

    const payload = row.payload || {};
    if (row.timestamp) lastTimestamp = row.timestamp;
    if (row.type === "session_meta") meta = payload;

    if (row.type === "event_msg" && payload.type === "thread_name_updated" && payload.thread_name) {
      title = payload.thread_name;
    }

    if (!firstUser && row.type === "event_msg" && payload.type === "user_message" && payload.message) {
      const text = payload.message.trim();
      if (text && !text.includes("<environment_context>")) {
        firstUser = text.split(/\n/)[0].slice(0, 512);
      }
    }

    if (!firstUser && row.type === "response_item" && payload.type === "message" && payload.role === "user") {
      const text = (payload.content || []).map((item) => item.text || "").join("").trim();
      if (text && !text.includes("<environment_context>")) {
        firstUser = text.split(/\n/)[0].slice(0, 512);
      }
    }
  }

  if (!meta?.id || !meta?.timestamp) {
    throw new Error(`Missing session_meta in ${file}`);
  }

  if (!title) title = firstUser.slice(0, 80) || path.basename(file);
  const targetPath = file.replace(archiveRaw, sessionsDir);
  const createdMs = Date.parse(meta.timestamp);
  const updatedMs = Date.parse(lastTimestamp || meta.timestamp);

  return {
    id: meta.id,
    rollout_path: targetPath,
    created_at: Math.floor(createdMs / 1000),
    updated_at: Math.floor(updatedMs / 1000),
    source: meta.source || "vscode",
    model_provider: meta.model_provider || "openai",
    cwd: meta.cwd || "",
    title,
    sandbox_policy: JSON.stringify({
      type: "workspace-write",
      writable_roots: meta.cwd ? [meta.cwd] : [],
      network_access: false,
      exclude_tmpdir_env_var: false,
      exclude_slash_tmp: false,
    }),
    approval_mode: "on-request",
    tokens_used: 0,
    has_user_event: firstUser ? 1 : 0,
    archived: 0,
    archived_at: null,
    git_sha: null,
    git_branch: null,
    git_origin_url: null,
    cli_version: meta.cli_version || "",
    first_user_message: firstUser,
    agent_nickname: null,
    agent_role: null,
    memory_mode: "enabled",
    model: null,
    reasoning_effort: null,
    agent_path: null,
    created_at_ms: createdMs,
    updated_at_ms: updatedMs,
    archive_path: file,
  };
}

function backupCurrentState() {
  fs.mkdirSync(backupDir, { recursive: true });
  for (const file of [
    sessionIndex,
    stateDb,
    `${stateDb}-wal`,
    `${stateDb}-shm`,
  ]) {
    if (fs.existsSync(file)) {
      fs.copyFileSync(file, path.join(backupDir, path.basename(file)));
    }
  }

  const sessionsBackup = path.join(backupDir, "sessions");
  if (fs.existsSync(sessionsDir)) {
    fs.cpSync(sessionsDir, sessionsBackup, { recursive: true });
  }
}

function copyRollouts(rows) {
  let copied = 0;
  let skipped = 0;
  for (const row of rows) {
    fs.mkdirSync(path.dirname(row.rollout_path), { recursive: true });
    if (fs.existsSync(row.rollout_path)) {
      skipped += 1;
      continue;
    }
    fs.copyFileSync(row.archive_path, row.rollout_path);
    copied += 1;
  }
  return { copied, skipped };
}

function updateSessionIndex(rows) {
  const byId = new Map();
  if (fs.existsSync(sessionIndex)) {
    for (const line of fs.readFileSync(sessionIndex, "utf8").split(/\n/).filter(Boolean)) {
      try {
        const item = JSON.parse(line);
        byId.set(item.id, item);
      } catch {
        // Ignore malformed legacy lines rather than blocking restoration.
      }
    }
  }

  for (const row of rows) {
    byId.set(row.id, {
      id: row.id,
      thread_name: row.title,
      updated_at: new Date(row.updated_at_ms).toISOString(),
    });
  }

  const lines = [...byId.values()]
    .sort((a, b) => String(a.updated_at).localeCompare(String(b.updated_at)))
    .map((item) => JSON.stringify(item));
  fs.writeFileSync(sessionIndex, `${lines.join("\n")}\n`, "utf8");
  return lines.length;
}

function q(value) {
  if (value === null || value === undefined) return "NULL";
  if (typeof value === "number") return String(Number.isFinite(value) ? value : 0);
  return `'${String(value).replace(/'/g, "''")}'`;
}

function updateThreads(rows) {
  const existingOutput = sh("sqlite3", [stateDb, "select id from threads;"]);
  const existing = new Set(existingOutput.trim().split(/\n/).filter(Boolean));
  const columns = [
    "id", "rollout_path", "created_at", "updated_at", "source", "model_provider",
    "cwd", "title", "sandbox_policy", "approval_mode", "tokens_used", "has_user_event",
    "archived", "archived_at", "git_sha", "git_branch", "git_origin_url", "cli_version",
    "first_user_message", "agent_nickname", "agent_role", "memory_mode", "model",
    "reasoning_effort", "agent_path", "created_at_ms", "updated_at_ms",
  ];

  let inserted = 0;
  for (const row of rows) {
    if (existing.has(row.id)) continue;
    const values = columns.map((column) => q(row[column])).join(", ");
    const sql = `insert into threads (${columns.join(", ")}) values (${values});`;
    sh("sqlite3", [stateDb, sql]);
    inserted += 1;
  }
  return inserted;
}

const rows = listRollouts().map(parseRollout);
backupCurrentState();
const copied = copyRollouts(rows);
const indexCount = updateSessionIndex(rows);
const inserted = updateThreads(rows);

const report = {
  restored_at: new Date().toISOString(),
  backup_dir: backupDir,
  archive_raw: archiveRaw,
  total_archive_rows: rows.length,
  copied_rollout_files: copied.copied,
  skipped_existing_rollout_files: copied.skipped,
  session_index_entries: indexCount,
  inserted_threads: inserted,
};

fs.writeFileSync(
  path.join(outDir, "ttgame_codex_restore_result.json"),
  JSON.stringify(report, null, 2),
  "utf8",
);

console.log(JSON.stringify(report, null, 2));

